/**
 * Joins class names, skipping every falsy value (`undefined`, `null`, `false`, `0` and the empty string).
 *
 * Internal helper: it is intentionally not exported from `utilities/index.ts`.
 *
 * @example
 * classNames( "dxFoo", isActive && "dxFoo--active", props.className ) // "dxFoo dxFoo--active my-class"
 */
export const classNames = ( ...values: Array<string | false | null | undefined | 0> ): string =>
    values.filter( Boolean ).join( " " );
